namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications = new();
    private int _nextId = 1;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notification centre!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post."),
        });
    }

    /// <summary>
    /// Returns all notifications.
    /// </summary>
    public IReadOnlyList<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns only notifications created after <paramref name="since"/>.
    /// </summary>
    public IReadOnlyList<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    /// <summary>
    /// Simulates an external system pushing a new notification.
    /// Called by the background generator so there is something to poll for.
    /// </summary>
    public void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(CreateNotification(message));
        }
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// A hosted service that periodically adds fake notifications so there is
/// new data for the polling page to discover.
/// </summary>
public class NotificationGeneratorService : BackgroundService
{
    private static readonly string[] SampleMessages =
    [
        "Deployment completed.",
        "New user signed up.",
        "Server CPU spike detected.",
        "Backup finished successfully.",
        "Scheduled maintenance reminder.",
        "Your report is ready to download.",
        "Payment received.",
        "Disk space running low.",
    ];

    private readonly NotificationService _notificationService;

    public NotificationGeneratorService(NotificationService notificationService)
    {
        _notificationService = notificationService;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var rng = new Random();
        while (!stoppingToken.IsCancellationRequested)
        {
            // Add a new notification every 7-12 seconds.
            await Task.Delay(TimeSpan.FromSeconds(rng.Next(7, 13)), stoppingToken);
            var message = SampleMessages[rng.Next(SampleMessages.Length)];
            _notificationService.Add(message);
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = new();
    private CancellationTokenSource? _cts;
    private DateTime _lastChecked;

    // OnInitialized runs during both prerender AND interactive init.
    // We load the initial data here so it is included in the server-rendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetAll().ToList();
        _lastChecked = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // OnAfterRender is only called when the component is live in the browser.
    // On the very first interactive render we start the polling loop.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = NotificationService.GetSince(_lastChecked);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _lastChecked = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

